  -- Lesson 26: বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ১

  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_2, 'বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ১', 'lesson-26', 'Lesson 26 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের পরিচয়, পরিবার ও শিক্ষা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. নিজের সম্পর্কে যেকোনো প্রশ্নের উত্তর ভাবনাচিন্তা ছাড়াই দিতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. পরিবার ও শিক্ষা নিয়ে ৩০+ প্রশ্নের প্রস্তুত উত্তর পাবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. সাক্ষাৎকার বা নতুন পরিচয়ে আত্মবিশ্বাসের সাথে কথা বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. প্রতিটি প্রশ্নকে নিজের তথ্য দিয়ে বদলে নেওয়ার কৌশল শিখবে।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"📖 কীভাবে ব্যবহার করবে প্রতিটি উত্তর একটা \"কাঠামো\" — হুবহু মুখস্থ না করে নিজের তথ্য বসিয়ে নাও। জোরে পড়ো, তারপর বই বন্ধ করে নিজের ভাষায় বলার চেষ্টা করো।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — নিজের পরিচয় (Personal Information)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your name?  —  তোমার নাম কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My name is Misbah Uddin."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How old are you?  —  তোমার বয়স কত?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am eighteen years old."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where are you from?  —  তুমি কোথা থেকে এসেছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am from Dhaka, Bangladesh."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where do you live?  —  তুমি কোথায় থাকো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I live in Mirpur, Dhaka."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your nationality?  —  তোমার জাতীয়তা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am a Bangladeshi."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your mother tongue?  —  তোমার মাতৃভাষা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My mother tongue is Bangla."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Can you speak English?  —  তুমি কি ইংরেজি বলতে পারো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I can speak a little English."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What languages do you speak?  —  তুমি কোন কোন ভাষা বলো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I speak Bangla and a little English."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your date of birth?  —  তোমার জন্মতারিখ কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I was born on 15 March 2008."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Are you married or single?  —  তুমি বিবাহিত না অবিবাহিত?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am single."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your religion?  —  তোমার ধর্ম কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am a Muslim."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your hobby?  —  তোমার শখ কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My hobby is reading books."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — পরিবার (Family)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Tell me about your family.  —  তোমার পরিবার সম্পর্কে বলো।"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I have a small family. There are five members — my parents, one brother, one sister and me."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How many members are there in your family?  —  তোমার পরিবারে কতজন সদস্য?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: There are five members in my family."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What does your father do?  —  তোমার বাবা কী করেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My father is a farmer. / My father is a businessman."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What does your mother do?  —  তোমার মা কী করেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My mother is a housewife. / My mother is a teacher."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you have any brothers or sisters?  —  তোমার কোনো ভাই-বোন আছে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I have one brother and one sister."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Are you the eldest child?  —  তুমি কি সবার বড়?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, I am the youngest child in my family."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you live with your parents?  —  তুমি কি বাবা-মায়ের সাথে থাকো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I live with my parents."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where do your grandparents live?  —  তোমার দাদা-দাদি কোথায় থাকেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My grandparents live in our village."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Is your family close-knit?  —  তোমার পরিবার কি ঘনিষ্ঠ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, we are a very close family."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Who do you look up to in your family?  —  পরিবারে তুমি কাকে আদর্শ মানো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I look up to my father the most."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How do you help at home?  —  বাসায় তুমি কীভাবে সাহায্য করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I help my mother with household chores."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is a typical weekend like for your family?  —  তোমাদের পরিবারে সাপ্তাহিক ছুটি কেমন কাটে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: We usually have lunch together and visit relatives."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — শিক্ষা (Education)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What class do you study in?  —  তুমি কোন শ্রেণিতে পড়ো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I study in class ten."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Which school do you go to?  —  তুমি কোন স্কুলে পড়ো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I go to ABC High School."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your favourite subject?  —  তোমার প্রিয় বিষয় কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My favourite subject is English."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Why do you like that subject?  —  তুমি ঐ বিষয়টা কেন পছন্দ করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I like it because it helps me communicate with people."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Which subject do you find difficult?  —  কোন বিষয় তোমার কাছে কঠিন লাগে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I find mathematics a bit difficult."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How do you go to school?  —  তুমি কীভাবে স্কুলে যাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I go to school by bus."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How long does it take to reach school?  —  স্কুলে পৌঁছাতে কতক্ষণ লাগে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It takes about twenty minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Who is your favourite teacher?  —  তোমার প্রিয় শিক্ষক কে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My English teacher is my favourite teacher."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you want to become in future?  —  তুমি ভবিষ্যতে কী হতে চাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I want to become a doctor."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you like studying?  —  তোমার পড়াশোনা ভালো লাগে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I really enjoy studying, especially languages."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How many hours do you study every day?  —  তুমি প্রতিদিন কত ঘণ্টা পড়াশোনা করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I study about three hours every day."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What extracurricular activities do you do?  —  পড়াশোনার বাইরে তুমি কী করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I play cricket and I am a member of the debate club."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Have you passed your SSC exam?  —  তুমি কি এসএসসি পাস করেছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I passed my SSC exam last year with a GPA of 5."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What are your plans after finishing school?  —  স্কুল শেষ করার পর তোমার পরিকল্পনা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I plan to study science in college."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — এই বিষয়ে বাড়তি বাক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I come from a middle-class family."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি একটি মধ্যবিত্ত পরিবার থেকে এসেছি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"My parents always encourage me to study."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমার বাবা-মা সবসময় আমাকে পড়াশোনায় উৎসাহ দেন।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I am the first one in my family to go to college."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমার পরিবারে আমিই প্রথম কলেজে পড়ছি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I want to make my parents proud."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি আমার বাবা-মাকে গর্বিত করতে চাই।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Education is very important to me."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শিক্ষা আমার কাছে খুব গুরুত্বপূর্ণ।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am grateful for my teachers."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি আমার শিক্ষকদের প্রতি কৃতজ্ঞ।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৬ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ ৩০ মিনিটের কাজ"}]},{"type":"paragraph","content":[{"type":"text","text":"১. এই Lesson-এর ৩৮টি প্রশ্ন নিজের তথ্য দিয়ে লিখিতভাবে উত্তর দাও।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. প্রতিটি উত্তর জোরে ৩ বার বলো — খাতা না দেখে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. পরিবারের একজনকে বলো তোমাকে ইংরেজিতে ৫টি প্রশ্ন করতে — উত্তর দাও।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. আয়নার সামনে ২ মিনিট নিজের পরিচয় একটানা বলো।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 26 শেষ? যদি কেউ হঠাৎ যেকোনো ক্রমে এই প্রশ্নগুলো করলে তুমি ২-৩ সেকেন্ডের মধ্যে সাবলীলভাবে উত্তর দিতে পারো — তাহলে Lesson 26 তোমার হয়ে গেছে।"}]}]}]}'::jsonb, 'published', 'intermediate', 60, now())
  returning id into v_lesson;

  -- Lesson 27: বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ২

  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_2, 'বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ২', 'lesson-27', 'Lesson 27 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"স্বাস্থ্য, খাবার, শখ ও আবহাওয়া"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. অসুস্থতা ও স্বাস্থ্য নিয়ে কথা বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. খাবার নিয়ে পছন্দ-অপছন্দ প্রকাশ করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. শখ ও অবসর সময় নিয়ে সাবলীলভাবে বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. আবহাওয়া নিয়ে ছোট আলাপ (small talk) করতে পারবে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — স্বাস্থ্য (Health)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How are you feeling today?  —  আজ কেমন লাগছে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I am feeling well, thank you."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What''s wrong with you?  —  তোমার কী হয়েছে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I have a headache and a slight fever."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How long have you been sick?  —  কতদিন ধরে অসুস্থ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I have been sick for two days."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Have you seen a doctor?  —  তুমি কি ডাক্তার দেখিয়েছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I saw a doctor yesterday."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What did the doctor say?  —  ডাক্তার কী বললেন?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: He said I need to take rest and drink plenty of water."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Are you taking any medicine?  —  তুমি কি কোনো ওষুধ খাচ্ছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I am taking medicine twice a day."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you exercise regularly?  —  তুমি কি নিয়মিত ব্যায়াম করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I go for a walk every morning."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How do you stay healthy?  —  তুমি কীভাবে সুস্থ থাকো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I eat healthy food and sleep on time."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you smoke or drink?  —  তুমি কি ধূমপান বা মদ্যপান করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, I neither smoke nor drink."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How many hours do you sleep at night?  —  তুমি রাতে কত ঘণ্টা ঘুমাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I sleep about seven hours a night."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — খাবার (Food)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your favourite food?  —  তোমার প্রিয় খাবার কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My favourite food is rice with fish curry."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What did you have for breakfast?  —  নাস্তায় কী খেয়েছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I had bread and an egg for breakfast."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you like spicy food?  —  তুমি কি ঝাল খাবার পছন্দ করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I like spicy food a lot."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Are you a vegetarian?  —  তুমি কি নিরামিষভোজী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, I am not. I eat both vegetables and meat."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your favourite fruit?  —  তোমার প্রিয় ফল কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My favourite fruit is mango."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Can you cook?  —  তুমি কি রান্না করতে পারো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I can cook simple dishes like rice and eggs."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is a popular dish in Bangladesh?  —  বাংলাদেশের জনপ্রিয় খাবার কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Rice and hilsa fish curry is very popular."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you like fast food?  —  তুমি কি ফাস্ট ফুড পছন্দ করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I like it sometimes, but I prefer home-cooked food."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How often do you eat out?  —  তুমি কতবার বাইরে খাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I eat out once or twice a month."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you usually drink?  —  তুমি সাধারণত কী পান করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I usually drink water and sometimes tea."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — শখ ও অবসর সময় (Hobbies & Free Time)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you do in your free time?  —  অবসর সময়ে তুমি কী করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I read books and listen to music."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your hobby?  —  তোমার শখ কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My hobby is collecting stamps."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you like reading books?  —  তোমার বই পড়তে ভালো লাগে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I love reading, especially novels."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What kind of music do you like?  —  তুমি কেমন গান পছন্দ করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I like folk and modern Bangla songs."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you play any sports?  —  তুমি কি কোনো খেলা খেলো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I play cricket with my friends."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How often do you watch movies?  —  তুমি কতবার সিনেমা দেখো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I watch movies once a week."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you like travelling?  —  তোমার ভ্রমণ করতে ভালো লাগে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I love travelling to new places."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your favourite place to visit?  —  বেড়াতে তোমার প্রিয় জায়গা কোনটা?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Cox''s Bazar is my favourite place."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you do with friends on weekends?  —  সপ্তাহান্তে বন্ধুদের সাথে তুমি কী করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: We usually play cricket or watch a movie together."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you use social media?  —  তুমি কি সোশ্যাল মিডিয়া ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I use Facebook and YouTube."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — আবহাওয়া (Weather) — Small Talk"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What''s the weather like today?  —  আজ আবহাওয়া কেমন?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It''s sunny and quite hot today."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Is it going to rain today?  —  আজ কি বৃষ্টি হবে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It looks like it might rain in the afternoon."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What season do you like best?  —  কোন ঋতু তোমার সবচেয়ে পছন্দ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I like winter the most."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Why do you like that season?  —  ঐ ঋতু কেন পছন্দ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Because the weather is cool and pleasant."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How hot does it get in summer here?  —  গ্রীষ্মে এখানে কতটা গরম পড়ে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It can get very hot, sometimes over 35 degrees."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Does it snow in Bangladesh?  —  বাংলাদেশে কি বরফ পড়ে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, it never snows in Bangladesh."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How is the weather during the monsoon?  —  বর্ষাকালে আবহাওয়া কেমন থাকে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It rains heavily and the weather stays humid."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you carry an umbrella?  —  তুমি কি ছাতা নিয়ে বের হও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I always carry one during the rainy season."}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🗣️ আবহাওয়া নিয়ে ৬টি Small Talk বাক্য Lovely weather today, isn''t it? — আজ আবহাওয়া চমৎকার, তাই না? It is really hot today. — আজ সত্যিই গরম। Looks like it might rain. — মনে হচ্ছে বৃষ্টি হবে। It is freezing cold. — খুব ঠান্ডা। The weather has been unpredictable lately. — আজকাল আবহাওয়া অস্থির। I love this breeze. — এই বাতাসটা দারুণ লাগছে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — দরকারি বাক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am allergic to peanuts."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমার চিনাবাদামে অ্যালার্জি আছে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I follow a balanced diet."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি সুষম খাদ্যাভ্যাস মেনে চলি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I try to avoid junk food."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি জাংক ফুড এড়িয়ে চলার চেষ্টা করি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Reading relaxes my mind."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বই পড়া আমার মনকে শান্ত করে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I picked up this hobby last year."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি গত বছর এই শখটা শুরু করেছি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"The weather here changes quickly."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এখানকার আবহাওয়া দ্রুত বদলায়।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৭ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ ৩০ মিনিটের কাজ"}]},{"type":"paragraph","content":[{"type":"text","text":"১. এই Lesson-এর ৩৬টি প্রশ্নের উত্তর লিখিতভাবে দাও।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. প্রতিটি অংশ (স্বাস্থ্য, খাবার, শখ, আবহাওয়া) থেকে ৫টি করে প্রশ্ন মুখস্থ করো।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. আজকের আবহাওয়া নিয়ে কাউকে ইংরেজিতে ২টি বাক্য বলো।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 27 শেষ? যদি কেউ \"How is the weather today?\" বা \"What is your hobby?\" জিজ্ঞেস করলে তুমি না থেমে স্বাভাবিকভাবে উত্তর দিতে পারো — তাহলে Lesson 27 তোমার হয়ে গেছে।"}]}]}]}'::jsonb, 'published', 'intermediate', 60, now())
  returning id into v_lesson;

  -- Lesson 28: বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ৩

  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_2, 'বিষয়ভিত্তিক প্রশ্ন-উত্তর — পর্ব ৩', 'lesson-28', 'Lesson 28 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রযুক্তি, পরিবেশ, কর্মজীবন ও বাংলাদেশ"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. প্রযুক্তি ও ইন্টারনেট নিয়ে মতামত প্রকাশ করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. পরিবেশ বিষয়ে সহজ আলোচনা করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. কর্মজীবন ও ভবিষ্যৎ পরিকল্পনা নিয়ে কথা বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. বিদেশিকে বাংলাদেশ সম্পর্কে পরিচয় করাতে পারবে — এটি খুবই সাধারণভাবে জিজ্ঞাসা করা হয়।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — প্রযুক্তি (Technology)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you use a smartphone?  —  তুমি কি স্মার্টফোন ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I use a smartphone every day."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How much time do you spend on your phone?  —  ফোনে কত সময় কাটাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I spend about three hours a day on my phone."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you use the internet for?  —  ইন্টারনেট কী কাজে ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I use it for studying, chatting, and watching videos."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you think technology has made life easier?  —  প্রযুক্তি কি জীবন সহজ করেছে বলে মনে করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, it has made communication and learning much easier."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What are the disadvantages of technology?  —  প্রযুক্তির অসুবিধা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: It can be addictive and reduce face-to-face communication."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you use a computer?  —  তুমি কি কম্পিউটার ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I use a computer for my studies."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Have you used AI tools like Claude or ChatGPT?  —  তুমি কি এআই টুল ব্যবহার করেছ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I use them to help with my studies."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you prefer reading books or e-books?  —  তুমি কি বই না ই-বুক পছন্দ করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I prefer reading printed books."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — পরিবেশ (Environment)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your opinion on climate change?  —  জলবায়ু পরিবর্তন নিয়ে তোমার মতামত কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I think climate change is a serious problem that needs urgent action."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How can we protect the environment?  —  আমরা কীভাবে পরিবেশ রক্ষা করতে পারি?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: We can plant more trees and reduce plastic use."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you recycle?  —  তুমি কি পুনর্ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I try to recycle paper and plastic whenever possible."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Is pollution a big problem in your city?  —  তোমার শহরে দূষণ কি বড় সমস্যা?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, air and water pollution are serious problems in Dhaka."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What can students do to help the environment?  —  ছাত্ররা পরিবেশের জন্য কী করতে পারে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Students can plant trees and avoid using plastic bags."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you use plastic bags?  —  তুমি কি প্লাস্টিক ব্যাগ ব্যবহার করো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, I try to use cloth bags instead."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Why is planting trees important?  —  গাছ লাগানো কেন গুরুত্বপূর্ণ?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Trees give us oxygen and keep the environment clean."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — কর্মজীবন ও ভবিষ্যৎ (Work & Future)"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you want to be in the future?  —  তুমি ভবিষ্যতে কী হতে চাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I want to become an engineer."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Why do you want to become that?  —  কেন তুমি এটা হতে চাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Because I love solving problems and building things."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What are your future plans?  —  তোমার ভবিষ্যৎ পরিকল্পনা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I plan to finish my studies and get a good job."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you have a part-time job?  —  তোমার কি পার্টটাইম চাকরি আছে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: No, I am focusing on my studies right now."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What skills do you want to learn?  —  তুমি কী দক্ষতা শিখতে চাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I want to improve my English and learn computer programming."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where do you see yourself in five years?  —  পাঁচ বছর পর নিজেকে কোথায় দেখো?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I see myself working in a good company and supporting my family."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is your dream job?  —  তোমার স্বপ্নের চাকরি কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My dream job is to work as a software engineer."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you want to work abroad?  —  তুমি কি বিদেশে কাজ করতে চাও?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Yes, I would like to work abroad for a few years."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What motivates you to work hard?  —  তোমাকে পরিশ্রম করতে কী অনুপ্রাণিত করে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: My family and my dreams motivate me to work hard."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — বাংলাদেশ সম্পর্কে (About Bangladesh)"}]},{"type":"paragraph","content":[{"type":"text","text":"বিদেশিরা প্রায়ই এই প্রশ্নগুলো করে। এই উত্তরগুলো তোমাকে দেশের একজন ভালো \"রাষ্ট্রদূত\" বানাবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where is Bangladesh located?  —  বাংলাদেশ কোথায় অবস্থিত?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Bangladesh is located in South Asia, next to India."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is the capital of Bangladesh?  —  বাংলাদেশের রাজধানী কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: The capital of Bangladesh is Dhaka."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What language do people speak in Bangladesh?  —  বাংলাদেশে মানুষ কোন ভাষায় কথা বলে?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: People in Bangladesh speak Bangla."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is Bangladesh famous for?  —  বাংলাদেশ কীসের জন্য বিখ্যাত?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Bangladesh is famous for the Sundarbans, jute, and its rivers."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is the national fruit of Bangladesh?  —  বাংলাদেশের জাতীয় ফল কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: The national fruit of Bangladesh is jackfruit."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is the traditional dress of Bangladesh?  —  বাংলাদেশের ঐতিহ্যবাহী পোশাক কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Saree for women and panjabi or lungi for men."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is a popular festival in Bangladesh?  —  বাংলাদেশের একটি জনপ্রিয় উৎসব কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Pahela Baishakh, the Bengali New Year, is very popular."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: When did Bangladesh become independent?  —  বাংলাদেশ কবে স্বাধীন হয়েছিল?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: Bangladesh became independent in 1971."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What is the national sport of Bangladesh?  —  বাংলাদেশের জাতীয় খেলা কী?"}]},{"type":"paragraph","content":[{"type":"text","text":"A: The national sport is Kabaddi, but cricket is the most popular."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Can you recommend a place to visit in Bangladesh?  —  বাংলাদেশে দেখার মতো একটা জায়গা বলো।"}]},{"type":"paragraph","content":[{"type":"text","text":"A: I would recommend Cox''s Bazar, the longest sea beach in the world."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — দরকারি বাক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I believe technology should be used wisely."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি মনে করি প্রযুক্তি বুদ্ধিমত্তার সাথে ব্যবহার করা উচিত।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"We all have a responsibility to protect the environment."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিবেশ রক্ষার দায়িত্ব আমাদের সবার।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am still exploring my career options."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি এখনো আমার ক্যারিয়ারের সম্ভাবনা খুঁজছি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Bangladesh is a land of rivers."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলাদেশ নদীর দেশ।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am proud to be a Bangladeshi."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি একজন বাংলাদেশি হতে গর্বিত।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৭ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ ৩০ মিনিটের কাজ"}]},{"type":"paragraph","content":[{"type":"text","text":"১. এই Lesson-এর ৩৪টি প্রশ্নের উত্তর লিখিতভাবে দাও।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. বাংলাদেশ সম্পর্কে ১০টি প্রশ্নের উত্তর মুখস্থ করো — এটি সবচেয়ে বেশি জিজ্ঞাসিত।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. তোমার ভবিষ্যৎ পরিকল্পনা নিয়ে ১ মিনিট একটানা বলার অনুশীলন করো।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 28 শেষ? যদি একজন বিদেশি হঠাৎ তোমাকে বাংলাদেশ সম্পর্কে জিজ্ঞেস করলে তুমি গর্বের সাথে ও দ্বিধাহীনভাবে উত্তর দিতে পারো — তাহলে Lesson 28 তোমার হয়ে গেছে।"}]}]}]}'::jsonb, 'published', 'intermediate', 60, now())
  returning id into v_lesson;

