  values (v_part_2, 'দৈনন্দিন কথোপকথন — পর্ব ২', 'lesson-29', 'Lesson 29 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যাংক, পোস্ট অফিস, বিমানবন্দর ও হোটেল"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. ব্যাংকে অ্যাকাউন্ট খোলা বা টাকা তোলার কথা বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. পোস্ট অফিসে চিঠি বা পার্সেল পাঠাতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. বিমানবন্দরে চেক-ইন ও ইমিগ্রেশনে কথা বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. হোটেল বুকিং ও রিসেপশনে কথা বলতে পারবে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — ব্যাংকে (At the Bank)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I want to open an account."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আই ওয়ন্ট টু ওৌপেন অ্যান অ্যাকাউন্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমি একটা অ্যাকাউন্ট খুলতে চাই"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I want to withdraw some money."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আই ওয়ন্ট টু উইদড্র"}]}]},{"type":"tableCell","content":[{"ty